header = '''<header><a class="brand" href="index.html" aria-label="E y V, inicio"><img src="assets/ev-symbol-v2.png" alt="" width="66" height="66"><span class="brand-wordmark">E & V<small>SOLUCIONES INTEGRALES</small></span></a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="main-nav">Menú</button><nav id="main-nav" aria-label="Navegación principal"><a href="index.html#servicios">Servicios</a><a href="tienda.html">Tienda</a><a href="index.html#nosotros">Nosotros</a><a href="index.html#proceso">Cómo trabajamos</a></nav><a class="button small header-quote" href="index.html#contacto">Cotiza tu proyecto</a></header>'''
home = re.sub(r'<header>.*?</header>', header, home, count=1, flags=re.S)
