(root / 'index.html').write_text(home, encoding='utf-8')
head = home.split('<body>')[0]
footer = '<footer>' + home.split('<footer>',1)[1]

def page(title,description,content):
    page_head = re.sub(r'<title>.*?</title>', '<title>'+escape(title)+' · E & V</title>', head)
    page_head = re.sub(r'<meta name="description" content="[^"]*">', '<meta name="description" content="'+escape(description,quote=True)+'">',page_head)
    return page_head+'<body>'+header+content+footer

