    content = f'''<main id="inicio"><section class="detail-hero frame"><div class="breadcrumbs"><a href="index.html">Inicio</a><span>/</span><a href="index.html#servicios">Servicios</a><span>/</span><span>{s['name']}</span></div><span class="label">SERVICIO {number:02d} / E & V</span><h1>{s['title']}</h1><div class="detail-intro"><p>{s['intro']}</p><a class="button" href="{whatsapp}" target="_blank" rel="noopener">Consultar este servicio</a></div></section><section class="detail-scope frame"><div class="section-heading"><span class="label">EL ALCANCE</span><h2>¿EN QUÉ TE AYUDAMOS?</h2></div><div class="scope-grid">{cards}</div></section><section class="detail-context frame"><div><span class="label">PARA TU PROYECTO</span><h2>UNA SOLUCIÓN<br>PARA TU ESPACIO.</h2><p>{s['when']}</p></div><aside><span class="label">ANTES DE COTIZAR</span><h3>Cuéntanos los detalles.</h3><p>{s['prepare']}</p><p class="scope-note">El alcance, los materiales, el costo y los plazos se acuerdan en la cotización.</p><a class="text-link" href="{whatsapp}" target="_blank" rel="noopener">Hablar con E & V</a></aside></section><section class="faqs frame"><div><span class="label">RESOLVEMOS TUS DUDAS</span><h2>ANTES DE<br>EMPEZAR.</h2></div><div>{faqs}</div></section><section class="related-shop frame"><div><span class="label">SERVICIOS + PRODUCTOS</span><h2>COMPLETA TU PROYECTO.</h2><p>Consulta los productos relacionados y la posibilidad de incluir su instalación.</p></div><a class="button" href="tienda.html?categoria={s['category']}">Ver productos relacionados</a></section></main>'''
